{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 아파트 엘리베이터에서 강아지 오줌을 쌌을 때 바로 닦아야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제7조제3항제3호에 따르면, 등록대상동물의 배설물 중 소변의 경우에는 공동주택의 엘리베이터·계단 등 건물 내부의 공용공간 및 평상·의자 등 사람이 눕거나 앉을 수 있는 기구 위의 것으로 한정하며, 그러한 배설물이 생겼을 때에는 즉시 수거하여야 합니다. 아파트 엘리베이터는 공동주택의 엘리베이터 등 건물 내부의 공용공간에 해당하므로, 그 위에서 강아지 오줌이 생겼다면 바로 닦아야 합니다.",
          "b_ids": "동물보호:제7조제3항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
